from pathlib import Path
import os

ROOT = Path(r"c:\Users\DELL\OneDrive\Desktop\shanzo")


def find_matching_close_div(html: str, start: int) -> int:
    depth = 0
    i = start
    while i < len(html):
        next_open = html.find('<div', i)
        next_close = html.find('</div>', i)
        if next_open == -1 and next_close == -1:
            return -1
        if next_open != -1 and (next_close == -1 or next_open < next_close):
            depth += 1
            i = next_open + 4
        else:
            depth -= 1
            i = next_close + 6
            if depth == 0:
                return i
    return -1


def rel_prefix(file_path: Path) -> str:
    rel = os.path.relpath(ROOT, file_path.parent)
    return '' if rel in ('.', '') else rel + '/'


