def mobile_menu(prefix: str) -> str:
    items = [
        ("Data Management", prefix + "pages/data-management.html"),
        ("Data Integration", prefix + "pages/data-integration.html"),
        ("Data Visualization", prefix + "services/data-visualization.html"),
        ("Software Development &amp; Automation", prefix + "services/software-development.html"),
        ("Consulting &amp; Managed Services", prefix + "services/consulting-managed-services.html"),
        ("Enterprise Automation", prefix + "services/enterprise-automation.html"),
        ("View All Services", prefix + "pages/services.html"),
    ]
    links = ''.join(f'<a class="mobile-nav-link" href="{href}">{label}</a>' for label, href in items)
    return '<div class="mobile-nav-panel" data-mobile-panel="services">' + links + '</div>'


for html_file in ROOT.rglob('*.html'):
    original = html_file.read_text(encoding='utf-8')
    updated = original
    prefix = rel_prefix(html_file)

    desk_start = updated.find('<div class="mega mega--wide" id="menu-services"')
    if desk_start != -1:
        desk_end = find_matching_close_div(updated, desk_start)
        if desk_end != -1:
            updated = updated[:desk_start] + desktop_menu(prefix) + updated[desk_end:]

    mobile_group_start = updated.find('<div class="mobile-nav-group" data-mobile-group="services">')
    if mobile_group_start != -1:
        mobile_group_end = find_matching_close_div(updated, mobile_group_start)
        if mobile_group_end != -1:
            mobile_group = (
                '<div class="mobile-nav-group" data-mobile-group="services">'
                '<button class="mobile-nav-trigger" type="button" aria-expanded="false" data-mobile-trigger="services">'
                '<span>Services</span>'
                '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><polyline points="6 9 12 15 18 9" /></svg>'
                '</button>'
                f'{mobile_menu(prefix)}'
                '</div>'
            )
            updated = updated[:mobile_group_start] + mobile_group + updated[mobile_group_end:]

    if updated != original:
        html_file.write_text(updated, encoding='utf-8')

